// src/api/partOrderAPI.js
import axios_api from "./axios";
import { apiPath } from "./config";

const host = apiPath("/buyer/partorder");

// 전체 발주 조회
export const getPartOrders = async () => {
  const res = await axios_api.get(host);
  return res.data;
};

// 완료된 발주(입고완료)만
export const getCompletedPartOrders = async () => {
  const res = await axios_api.get(apiPath("/buyer/partorder/completed"));
  return res.data;
};

// 등록
export const createPartOrder = async (formData) => {
  const payload = {
    buyerNo: Number(formData.buyerNo ?? formData.buyerComp) || null,
    partNo: Number(formData.partNo),
    poQty: Number(formData.poQty),
    poPrice: Number(formData.poPrice),
    poState: String(formData.poState || "입고대기"),
    poDate: String(formData.poDate || new Date().toISOString().slice(0, 10)),
    buyerAddr: String(formData.buyerAddr || ""),
    buyerComp: String(formData.buyerCompName || formData.buyerComp || ""), // 라벨용(옵션)
    partName: String(formData.partName || ""),                                // 라벨용(옵션)
  };
  if (!payload.buyerNo) throw new Error("구매처(buyerNo) 필수");
  if (!payload.partNo) throw new Error("partNo 필수");
  const res = await axios_api.post(host, payload);
  return res.data;
};

// 수정
export const updatePartOrder = async (poNo, formData) => {
  if (poNo == null) throw new Error("poNo 누락");
  const payload = {
    buyerNo: Number(formData.buyerNo ?? formData.buyerComp) || null,
    partNo: Number(formData.partNo),
    poQty: Number(formData.poQty),
    poPrice: Number(formData.poPrice),
    poState: String(formData.poState || "입고대기"),
    poDate: String(formData.poDate || new Date().toISOString().slice(0, 10)),
    buyerAddr: String(formData.buyerAddr || ""),
    buyerComp: String(formData.buyerCompName || formData.buyerComp || ""),
    partName: String(formData.partName || ""),
  };
  const res = await axios_api.put(apiPath(`/buyer/partorder/${poNo}`), payload);
  return res.data;
};

// 상태 패치
export const patchPartOrderState = async (poNo, poState) => {
  if (poNo == null) throw new Error("poNo 누락");
  const res = await axios_api.patch(apiPath(`/buyer/partorder/${poNo}/state`), { poState });
  return res.data;
};

// 삭제
export const deletePartOrder = async (poNo) => {
  const res = await axios_api.delete(apiPath(`/buyer/partorder/${poNo}`));
  return res.data;
};
